        "text": "String equality comparison",
        "refs": ["Q0004"],
        "claims": [
          {
            "text": "Instead we need to use the equals method of string objects.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0004"],
            "related_refs": []
          }
